using Servicio.RetazoMarket.Business.DTOs.Descuento;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;public static class DescuentoBusinessMapper {public static DescuentoDataModel ToDataModel(CrearDescuentoRequest r)=>new(){id_producto=r.id_producto,cantidad_minima=r.cantidad_minima,porcentaje=r.porcentaje,estado=r.estado.Trim().ToUpperInvariant()};public static DescuentoDataModel ToDataModel(ActualizarDescuentoRequest r)=>new(){id_descuento=r.id_descuento,id_producto=r.id_producto,cantidad_minima=r.cantidad_minima,porcentaje=r.porcentaje,estado=r.estado.Trim().ToUpperInvariant()};public static DescuentoResponse ToResponse(DescuentoDataModel m)=>new(){id_descuento=m.id_descuento,id_producto=m.id_producto,cantidad_minima=m.cantidad_minima,porcentaje=m.porcentaje,estado=m.estado,producto_nombre=m.Producto?.prod_nombre};}
